import copy
from types import NoneType

import pytest

from trudag.config import GeneralConfig
from trudag.dotstop.core.constants import DEFAULT_GENERAL_CONFIG
from trudag.dotstop.core.exception import ConfigError


@pytest.fixture
def test_config(tmp_path):
    return copy.deepcopy(DEFAULT_GENERAL_CONFIG)


def test_invalid_config(test_config):
    test_config["publish"].update({"reports": [{}]})
    # We should raise errors when taking invalid config from a file or from a custom config
    with pytest.raises(
        ConfigError,
        match="Invalid data received from configuration content:.*",
    ):
        GeneralConfig(test_config)


def test_default_config(test_config):
    config = GeneralConfig({})
    assert config == GeneralConfig(test_config)


def test_custom_config(test_config):
    def _test_fields(config):
        config = GeneralConfig(config)
        return (
            config.get(["publish", "reports", "TEST_PROJECT"]),
            config.get(["publish", "path"]) == "report/output/dir",
        )

    default_config_content = copy.deepcopy(DEFAULT_GENERAL_CONFIG)

    assert not all(_test_fields(default_config_content))

    test_config["publish"].update(
        {
            "reports": {
                "TEST_PROJECT": {
                    "include_non_normative": False,
                    "figures": {
                        "enable": False,
                        "data_rows_limit": 30,
                    },
                }
            },
            "path": "report/output/dir",
        }
    )

    assert all(_test_fields(test_config))
    # Just asserting to ensure we never change the default config through GeneralConfig ever.
    assert not all(_test_fields(default_config_content))


def test_config_update(test_config):
    old_path = "docs/doorstop"
    new_path = "new/path"
    updated_config = GeneralConfig(
        {
            "plot": {"output_path": new_path},
        }
    )
    assert updated_config.get(["plot", "output_path"]) == new_path
    assert updated_config.get(["publish"]) == test_config["publish"]
    assert updated_config.get(["scoring"]) == test_config["scoring"]
    assert updated_config.get(["artifacts"]) == test_config["artifacts"]


def test_config_add(test_config):
    ignore_paths = ["forty", "two"]
    updated_config = GeneralConfig({"dotstop": {"ignore_paths": ignore_paths}})
    assert updated_config.get(["dotstop", "ignore_paths"]) == ignore_paths
    assert updated_config.get(["publish"]) == test_config["publish"]
    assert updated_config.get(["scoring"]) == test_config["scoring"]
    assert updated_config.get(["artifacts"]) == test_config["artifacts"]


def test_config_get(test_config):
    assert isinstance(
        GeneralConfig(test_config).get(["publish", "reports", "TSF", "preamble"]), str
    )
    assert isinstance(
        GeneralConfig(test_config).get(["publish", "reports", "TSF", "figures"]), dict
    )
    assert isinstance(
        GeneralConfig(test_config).get(["reports", "TSF", "NON_EXISTENT_KEY"]), NoneType
    )


def test_config_safe_get(test_config):
    custom_config = GeneralConfig(test_config)

    # Initially, we expect the safe get method to return early with the correct value from the custom config
    assert isinstance(
        custom_config.safe_get(["publish", "reports", "TSF", "preamble"]),
        str,
    )

    del custom_config.content["publish"]
    # We expect normal get method to fail to get deleted configuration content.
    assert isinstance(
        custom_config.get(["publish", "reports", "TSF", "preamble"]),
        NoneType,
    )
    assert isinstance(
        custom_config.get(["publish", "reports", "TSF", "figures"]),
        NoneType,
    )

    # We expect the safe_get method to fallback on the default configuration to get the requested keys.
    assert isinstance(
        custom_config.safe_get(["publish", "reports", "TSF", "preamble"]),
        str,
    )
    assert isinstance(
        custom_config.safe_get(["publish", "reports", "TSF", "figures"]),
        dict,
    )
    pytest.raises
    with pytest.raises(
        ValueError,
        match="No value found for the keys: publish, reports, TSF, NON_EXISTENT_KEY in the fallback default configuration!",
    ):
        assert custom_config.safe_get(["publish", "reports", "TSF", "NON_EXISTENT_KEY"])
